        int n = scanner.nextInt();
        int m = scanner.nextInt();
        if (n > m) {
            int temp = n;
            n = m;
            m = temp;
        }
        int sizeN = 1 << n;
        int sizeNMask = sizeN - 1;
        int[][] current = new int[sizeN][sizeN];
